//! Names and settings of the providers and transports v13 removed, which
//! `V13-CAPITAL-REMOVED` and `V13-MAIL-REMOVED` locate.

/// Whether a `.env` line selects or configures Lemon Squeezy, the only
/// removed provider that billing code generated by 12.x accepted:
/// `BILLING_PROVIDER=lemonsqueezy` or its `BILLING_STORE_ID` setting.
pub(crate) fn removed_billing_setting(line: &str) -> bool {
    let line = line.trim();
    let line = line.strip_prefix("export ").unwrap_or(line);
    let Some((key, value)) = line.split_once('=') else {
        return false;
    };
    let value = value.split(" #").next().unwrap_or(value);
    let value = value.trim().trim_matches(['"', '\'']);
    match key.trim() {
        "BILLING_PROVIDER" => value.eq_ignore_ascii_case("lemonsqueezy"),
        "BILLING_STORE_ID" => true,
        _ => false,
    }
}

